<div class="section-heading"><div><span class="eyebrow">ADMINISTRAÇÃO</span><h1>Pedidos<span class="accent">.</span></h1></div><a class="btn" href="<?= e(url('admin/pedidos/form')) ?>">+ Criar pedido</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Cliente</th><th>Situação</th><th>Total</th><th>Ações</th></tr></thead><tbody><?php foreach ($rows as $p): ?><tr><td>#<?= e($p['id']) ?></td><td><?= e($p['cliente']) ?></td><td><span class="badge"><?= e($p['status']) ?></span></td><td><?= money($p['total']) ?></td><td><div class="actions"><a class="btn tiny quiet" href="<?= e(url('order',['id'=>$p['id']])) ?>">Detalhes</a><?php if ($p['status']==='rascunho'): ?><a class="btn tiny quiet" href="<?= e(url('admin/pedidos/form',['id'=>$p['id']])) ?>">Editar</a><?php endif; ?><?php $targets=match($p['status']){'rascunho'=>['confirmado'=>'Confirmar','cancelado'=>'Cancelar'],'confirmado'=>['concluido'=>'Concluir','cancelado'=>'Cancelar'],default=>[]};foreach ($targets as $status=>$label): ?><form data-confirm="<?= e($label) ?> este pedido?" method="post" action="<?= e(url('admin/pedidos/status')) ?>"><?= csrfField() ?><input type="hidden" name="id" value="<?= e($p['id']) ?>"><input type="hidden" name="status" value="<?= e($status) ?>"><button class="btn tiny quiet"><?= e($label) ?></button></form><?php endforeach; ?><?php if (in_array($p['status'],['rascunho','cancelado'],true)): ?><form data-confirm="Excluir este pedido e seus itens?" method="post" action="<?= e(url('admin/pedidos/delete')) ?>"><?= csrfField() ?><input type="hidden" name="id" value="<?= e($p['id']) ?>"><button class="btn tiny danger">Excluir</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty">Nenhum pedido cadastrado.</td></tr><?php endif; ?></tbody></table></div><p class="hint">Rascunhos podem ser editados. Confirmar baixa o estoque; cancelar um confirmado devolve as unidades. Concluídos permanecem no histórico.</p>
